#include <iostream>
using namespace std;

// Returns the nth Fibonacci number (F(0) = 0, F(1) = 1)
long long fibonacci(int n) {
    if (n <= 1)
        return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;
    cout << "Enter n: ";
    cin >> n;

    if (n < 0) {
        cout << "n must be non-negative." << endl;
        return 1;
    }

    cout << "Fibonacci(" << n << ") = " << fibonacci(n) << endl;
    return 0;
}
```

**How it works**
- Base cases: `F(0) = 0` and `F(1) = 1`.
- Recursive case: `F(n) = F(n-1) + F(n-2)`.

**Compile and run**
```bash
g++ -o fib fib.cpp
./fib
```

**Note:** This naive recursion has O(2ⁿ) time complexity, so it gets slow for n above ~40. For larger values, use memoization:

```cpp
#include <vector>

long long fibMemo(int n, std::vector<long long>& memo) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
}
// Usage: std::vector<long long> memo(n + 1, -1); fibMemo(n, memo);
```

This reduces the time complexity to O(n).

